      sections: [["तैयारी", ["52 पत्तों की गड्डी चार स्थानों में बाँटी जाती है: आप, लोमड़ी, पांडा और ऊदबिलाव। एक पत्ता ओल्ड मेड के रूप में चिह्नित है; बाकी समान रैंक की जोड़ियाँ बनाते हैं।"]], ["अपनी चाल", ["हाथ में समान रैंक की जोड़ी बनते ही वह अपने-आप हट जाती है। अपनी चाल में अगली सक्रिय बाज़ी से एक उल्टा पत्ता लें; आप केवल छिपी स्थिति चुनते हैं और प्रतिद्वंद्वी के पत्ते का चेहरा नहीं देखते।"]], ["मेज़ पढ़ें", ["प्रतिद्वंद्वी की पंक्तियाँ हाथ में बचे पत्ते और हटाई गई जोड़ियाँ दिखाती हैं। गायब हुई रैंक याद रखें और बिना देखे स्थिति चुनें; हर ड्रॉ अगली जोड़ी और आपके हाथ का जोखिम बदल सकता है।"]], ["खिलाड़ी और सेव जानकारी", ["जब केवल एक सक्रिय हाथ बचता है तो राउंड समाप्त होता है। परिणाम स्क्रीन अंतिम धारक और आपकी जीत या हार बताती है; जीत-हार के कुल आँकड़े और ध्वनि इसी ब्राउज़र में रह सकते हैं, पर रीसेट के बाद मौजूदा बाज़ी जारी नहीं रहती।"]]],
      faqTitle: "अक्सर पूछे जाने वाले प्रश्न", faq: [["कितने खिलाड़ी होते हैं?", "चार स्थान खेलते हैं: आप और लोमड़ी, पांडा तथा ऊदबिलाव नाम के तीन AI प्रतिद्वंद्वी।"], ["समान रैंक के पत्तों का क्या होता है?", "हाथ में समान रैंक की जोड़ी बनते ही वह अपने-आप हट जाती है।"], ["क्या मैं अपने हाथ का पत्ता देख या चुन सकता हूँ?", "नहीं। आपका हाथ खुला और केवल पढ़ने योग्य है; आप अगली सक्रिय प्रतिद्वंद्वी बाज़ी की छिपी स्थिति चुनते हैं।"], ["मैं कैसे जीतूँ?", "जोड़ियाँ हटाते रहें और ओल्ड मेड के जोखिम के साथ आखिरी सक्रिय हाथ बनने से बचें। परिणाम अंतिम धारक दिखाता है।"], ["क्या प्रगति सहेजी जाती है?", "जीत-हार के कुल आँकड़े और ध्वनि सेटिंग इसी ब्राउज़र में रह सकती हैं। मौजूदा बाज़ी एक राउंड है और खाते की ज़रूरत नहीं है।"]],
      relatedTitle: "संबंधित खेल", relatedIntro: "अलग तरह की अनिश्चितता वाला कार्ड गेम भी आज़माएँ।", relatedIds: ["war", "speed"],
